package com.comfymobile.app;
import org.json.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;

public final class ArtistCacheTest {
 static void check(boolean pass,String message){if(!pass)throw new AssertionError(message);}
 static final byte[] PNG={(byte)137,80,78,71,13,10,26,10,1,2,3,4};
 static final class Source implements ArtistCache.Source {int downloads;String version="1";Runnable duringDownload;boolean broken;public JSONArray catalog()throws Exception{JSONArray rows=new JSONArray();for(int i=0;i<4;i++)rows.put(new JSONObject().put("id","artist-"+i).put("name","artist "+i).put("label","画师"+i).put("option","画师"+i+" · artist "+i).put("preview_url","/anima_artist_gallery/preview/artist-"+i).put("preview_version",i==0?version:"1"));return rows;}public InputStream image(String route)throws Exception{downloads++;if(duringDownload!=null){Runnable action=duringDownload;duringDownload=null;action.run();}if(broken)throw new IOException("offline");return new ByteArrayInputStream(PNG);}}
 public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("artist-cache-").toFile();File generated=new File(root,"images");generated.mkdirs();File preserved=new File(generated,"keep.png");Files.write(preserved.toPath(),PNG);ArtistCache cache=new ArtistCache(root);Source source=new Source();cache.sync("http://pc:8188",source,state->{});check(source.downloads==4&&cache.state().getInt("cached")==4,"all previews automatically cached");cache.sync("http://pc:8188",source,state->{});check(source.downloads==4,"same versions reuse disk images");source.version="2";cache.sync("http://pc:8188",source,state->{});check(source.downloads==5,"only updated preview downloads again");cache=new ArtistCache(root);check(cache.state().getInt("cached")==4,"cache persists after reopening");cache.clear();check(cache.state().getInt("cached")==0&&cache.state().getJSONArray("rows").length()==0&&cache.state().getBoolean("cleared")&&preserved.isFile(),"clear removes examples and catalog while preserving generated gallery");
  final ArtistCache clearing=cache;source.duringDownload=()->{try{clearing.clear();}catch(Exception e){throw new RuntimeException(e);}};cache.sync("http://pc:8188",source,state->{});check(cache.state().getInt("cached")==0,"clear while downloading never restores deleted images");source.broken=true;try{cache.sync("http://pc:8188",source,state->{});throw new AssertionError("expected offline failure");}catch(IOException expected){}check(!cache.state().getBoolean("syncing"),"failed sync releases in-progress state");source.broken=false;cache.sync("http://pc:8188",source,state->{});check(cache.state().getInt("cached")==4,"partial/offline sync resumes");cache.sync("http://other-pc:8188",source,state->{});check(cache.state().getString("server").equals("http://other-pc:8188"),"server identity isolates cache keys");
  try{cache.file("../images/keep.png");throw new AssertionError("path traversal accepted");}catch(IOException expected){}check(preserved.isFile(),"generated images unaffected by all cache operations");System.out.println("PASS: artist example download/reuse/version update/reopen/clear isolation/clear-download race/offline recovery/server identity/path containment");}
}
